effect.shader:
vec4 u_xlat0;
vec3 u_xlat1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
float u_xlat7;
bool u_xlatb7;
float u_xlat8;
float u_xlat13;
float u_xlat14;
float u_xlat19;
float u_xlat20;
void main()
{
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlat1.x = _intensity * 0.125 + -0.200000018;
    u_xlat1.x = u_xlat0.x + (-u_xlat1.x);
    u_xlat1.x = u_xlat1.x * 3.33333349;
    u_xlat1.x = clamp(u_xlat1.x, 0.0, 1.0);
    u_xlat7 = u_xlat1.x * -2.0 + 3.0;
    u_xlat1.x = u_xlat1.x * u_xlat1.x;
    u_xlat13 = u_xlat1.x * u_xlat7;
    u_xlat19 = 2136.28125 / _intensity;
    u_xlat19 = u_xlat19 * 1.66666663;
    u_xlat2.xy = acScreenNorm.xy * vec2(0.707106411, 0.707106411);
    u_xlat2.x = u_xlat2.y + u_xlat2.x;
    u_xlat2.x = u_xlat19 * u_xlat2.x;
    u_xlat2.x = cos(u_xlat2.x);
    u_xlat2.x = u_xlat2.x * 0.25 + 0.5;
    u_xlat8 = acScreenNorm.x * 0.707106411 + (-u_xlat2.y);
    u_xlat19 = u_xlat19 * u_xlat8;
    u_xlat19 = cos(u_xlat19);
    u_xlat19 = u_xlat19 * 0.25 + u_xlat2.x;
    u_xlatb2.x = 0.300000012<u_xlat13;
    u_xlat1.x = u_xlat7 * u_xlat1.x + u_xlat19;
    u_xlat1.x = (u_xlatb2.x) ? u_xlat1.x : u_xlat13;
    u_xlat2 = acScreenNorm.xyxy + vec4(-0.00390625, -0.00390625, 0.00390625, -0.00390625);
    u_xlat3 = texture(inputImg, u_xlat2.xy);
    u_xlat7 = dot(u_xlat3, vec4(0.300000012, 0.589999974, 0.109999999, 0.25));
    u_xlat2 = texture(inputImg, u_xlat2.zw);
    u_xlat13 = dot(u_xlat2, vec4(0.300000012, 0.589999974, 0.109999999, 0.25));
    u_xlat2 = acScreenNorm.xyxy + vec4(-0.00390625, 0.0, -0.00390625, 0.00390625);
    u_xlat3 = texture(inputImg, u_xlat2.xy);
    u_xlat2.x = dot(u_xlat3, vec4(0.300000012, 0.589999974, 0.109999999, 0.25));
    u_xlat3 = texture(inputImg, u_xlat2.zw);
    u_xlat8 = dot(u_xlat3, vec4(0.300000012, 0.589999974, 0.109999999, 0.25));
    u_xlat3 = acScreenNorm.xyxy + vec4(0.0, 0.00390625, 0.00390625, 0.00390625);
    u_xlat4 = texture(inputImg, u_xlat3.xy);
    u_xlat14 = dot(u_xlat4, vec4(0.300000012, 0.589999974, 0.109999999, 0.25));
    u_xlat3 = texture(inputImg, u_xlat3.zw);
    u_xlat20 = dot(u_xlat3, vec4(0.300000012, 0.589999974, 0.109999999, 0.25));
    u_xlat3.x = u_xlat13 + u_xlat20;
    u_xlat3.x = u_xlat2.x * 2.0 + u_xlat3.x;
    u_xlat3.x = (-u_xlat7) + u_xlat3.x;
    u_xlat2.x = (-u_xlat2.x) * 2.0 + u_xlat3.x;
    u_xlat2.x = (-u_xlat8) + u_xlat2.x;
    u_xlat8 = u_xlat14 * 2.0 + u_xlat8;
    u_xlat8 = u_xlat20 + u_xlat8;
    u_xlat8 = (-u_xlat7) + u_xlat8;
    u_xlat7 = (-u_xlat7) * 2.0 + u_xlat8;
    u_xlat7 = (-u_xlat13) + u_xlat7;
    u_xlat7 = u_xlat7 * u_xlat7;
    u_xlat7 = u_xlat2.x * u_xlat2.x + u_xlat7;
    u_xlatb7 = 0.0399999991<u_xlat7;
    u_xlat7 = u_xlatb7 ? -1.0 : float(0.0);
    u_xlat1.x = u_xlat7 * u_xlat19 + u_xlat1.x;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat1.y = u_xlat0.w;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1.xxxy;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat5 = u_xlat0 * u_xlat5;
        u_xlat3 = u_xlat3 * u_xlat4 + u_xlat5;
        u_xlat0.x = u_xlat4.x * u_xlat3.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat0.x : u_xlat3.w;
        fragColor.xyz = u_xlat3.xyz;
    } else {
        u_xlat1.z = u_xlat0.w;
        fragColor = u_xlat1.xxxz;
    }
    return;
}
